// Records which npm packages end up in the shipped web UI, so that the
// repository's THIRD_PARTY_NOTICES (generated by `make notices`, see
// internal/tools/notices) covers exactly what is distributed.
//
// Every production build writes .notices/<kind>.json:
//   * embedded   (`nuxt generate`, e.g. `pnpm generate:embed`): the client
//                 bundle, which the gos3 binary embeds;
//   * standalone (`nuxt build`): the client bundle, the Node server bundle
//                 and the packages Nitro copies next to it
//                 (.output/server/node_modules).
//
// A package is listed when at least one of its modules renders code into an
// output chunk. Two kinds of shipped code have no module path inside the
// package and are mapped explicitly: helpers the bundlers inject as virtual
// modules (VIRTUAL_MODULES) and files generated at build time from a
// package's data (GENERATED_FROM).
import { existsSync } from 'node:fs'
import { mkdir, readdir, readFile, realpath, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { addVitePlugin, defineNuxtModule } from 'nuxt/kit'

/** Bundler helpers injected as virtual modules, by module id prefix. */
const VIRTUAL_MODULES: Array<[prefix: string, pkg: string]> = [
  ['\0vite/', 'vite'],
  ['\0rolldown/', 'rolldown'],
  ['\0plugin-vue:', '@vitejs/plugin-vue']
]

/**
 * Packages whose content ships in files generated at build time: the icon
 * set bundled by Nuxt Icon and the stylesheets Tailwind generates CSS from.
 */
const GENERATED_FROM = ['@iconify-json/lucide', 'tailwindcss']

/** One shipped package, as written to .notices/<kind>.json. */
interface PackageRef {
  name: string
  version: string
  /** Package directory (inside node_modules). */
  dir: string
}

/** The parts of a Rollup or Rolldown output chunk used here. */
interface ChunkLike {
  type: 'chunk' | 'asset'
  moduleIds?: readonly string[]
  modules?: Record<string, { renderedLength: number }>
}

const NODE_MODULES = '/node_modules/'
const STYLE_MODULE = /\.(css|scss|sass|less|styl|pcss|postcss)(\?|$)/

/** Returns the package directory of a module file inside node_modules. */
function packageDir(id: string): string | undefined {
  const file = id.split('?')[0]!.replaceAll('\\', '/')
  const i = file.lastIndexOf(NODE_MODULES)
  if (i < 0) return undefined
  const rest = file.slice(i + NODE_MODULES.length).split('/')
  // Not a package: node_modules/.cache, node_modules/.vite, ...
  if (!rest[0] || rest[0].startsWith('.')) return undefined
  const len = rest[0].startsWith('@') ? 2 : 1
  if (rest.length <= len) return undefined
  return file.slice(0, i + NODE_MODULES.length) + rest.slice(0, len).join('/')
}

/** Shipped package directories and package names (resolved later). */
interface Shipped {
  dirs: Set<string>
  names: Set<string>
}

/** Records the packages of the modules that render code into a bundle. */
function collectBundle(shipped: Shipped, bundle: Record<string, ChunkLike>): void {
  for (const out of Object.values(bundle)) {
    if (out.type !== 'chunk') continue
    for (const id of out.moduleIds ?? []) {
      // Style modules render nothing into JS chunks; their CSS is an asset.
      if (out.modules?.[id]?.renderedLength === 0 && !STYLE_MODULE.test(id)) continue
      const virtual = VIRTUAL_MODULES.find(([prefix]) => id.startsWith(prefix))
      if (virtual) {
        shipped.names.add(virtual[1])
        continue
      }
      const dir = id.startsWith('\0') ? undefined : packageDir(id)
      if (dir) shipped.dirs.add(dir)
    }
  }
}

async function readPackage(dir: string): Promise<PackageRef | undefined> {
  try {
    const pkg = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8')) as { name?: string, version?: string }
    if (!pkg.name || !pkg.version) return undefined
    return { name: pkg.name, version: pkg.version, dir: await realpath(dir) }
  } catch {
    return undefined
  }
}

/**
 * Finds a package in pnpm's virtual store (node_modules/.pnpm), which has
 * one directory per installed name@version (plus a peer dependency suffix).
 * Without a version, every installed version is returned.
 */
async function storeDirs(rootDir: string, name: string, version?: string): Promise<string[]> {
  const store = join(rootDir, 'node_modules', '.pnpm')
  const prefix = `${name.replace('/', '+')}@`
  const matches = new Map<string, string>()
  for (const entry of existsSync(store) ? await readdir(store) : []) {
    if (!entry.startsWith(prefix)) continue
    const v = entry.slice(prefix.length).split('_')[0]!
    const dir = join(store, entry, 'node_modules', name)
    if ((!version || v === version) && existsSync(dir)) matches.set(v, dir)
  }
  return [...matches.values()]
}

/**
 * Lists the packages Nitro copied below a node_modules directory: scoped
 * packages, nested node_modules, and .nitro/<name>@<version> for packages it
 * needs in several versions.
 */
async function copiedPackages(nodeModules: string): Promise<PackageRef[]> {
  const found: PackageRef[] = []
  const visit = async (dir: string): Promise<void> => {
    if (!existsSync(dir)) return
    for (const name of await readdir(dir)) {
      const path = join(dir, name)
      if (name.startsWith('@') || name === '.nitro') {
        await visit(path)
      } else if (!name.startsWith('.')) {
        const pkg = await readPackage(path)
        if (pkg) found.push(pkg)
        await visit(join(path, 'node_modules'))
      }
    }
  }
  await visit(nodeModules)
  return found
}

export default defineNuxtModule({
  meta: { name: 'gos3-third-party-notices' },
  setup(_options, nuxt) {
    if (nuxt.options.dev || nuxt.options._prepare) return
    const rootDir = nuxt.options.rootDir
    const shipped: Shipped = { dirs: new Set(), names: new Set(GENERATED_FROM) }

    addVitePlugin({
      name: 'gos3:third-party-notices',
      apply: 'build',
      generateBundle(_opts, bundle) {
        collectBundle(shipped, bundle as unknown as Record<string, ChunkLike>)
      }
    }, { server: false })

    nuxt.hook('nitro:init', (nitro) => {
      // `nuxt generate` (static output) builds a server bundle only to
      // prerender pages; `nuxt build` ships it.
      const shipsServer = !nitro.options.static
      const kind = shipsServer ? 'standalone' : 'embedded'
      if (shipsServer) {
        nitro.hooks.hook('rollup:before', (_nitro, config) => {
          const plugins = Array.isArray(config.plugins) ? config.plugins : config.plugins ? [config.plugins] : []
          plugins.push({
            name: 'gos3:third-party-notices',
            generateBundle(_opts, bundle) {
              collectBundle(shipped, bundle as unknown as Record<string, ChunkLike>)
            }
          })
          config.plugins = plugins
        })
      }

      // Never fails the build: a package that cannot be located is recorded
      // without a directory, and the notices generator reports it.
      nitro.hooks.hook('compiled', async () => {
        const packages = new Map<string, PackageRef>()
        const add = (pkg: PackageRef | undefined): void => {
          if (pkg) packages.set(pkg.dir || `${pkg.name}@${pkg.version}`, pkg)
        }
        const addFromStore = async (name: string, version?: string): Promise<void> => {
          const dirs = await storeDirs(rootDir, name, version)
          if (!dirs.length) add({ name, version: version ?? '', dir: '' })
          for (const dir of dirs) add(await readPackage(dir))
        }
        try {
          for (const dir of shipped.dirs) add(await readPackage(dir))
          for (const name of shipped.names) await addFromStore(name)
          if (shipsServer) {
            // The copies hold only the traced files, so list the originals.
            for (const copy of await copiedPackages(join(nitro.options.output.serverDir, 'node_modules'))) {
              await addFromStore(copy.name, copy.version)
            }
          }
          const list = [...packages.values()].sort((a, b) => a.name.localeCompare(b.name) || a.version.localeCompare(b.version))
          await mkdir(join(rootDir, '.notices'), { recursive: true })
          await writeFile(join(rootDir, '.notices', `${kind}.json`), `${JSON.stringify({ kind, packages: list }, null, 2)}\n`)
        } catch (err) {
          console.warn(`[third-party-notices] could not record the shipped packages: ${String(err)}`)
        }
      })
    })
  }
})
